from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parent
FILES={'content_dedup': {'contract.json': '{\n  "package": "content_dedup",\n  "objective": "Build a content-addressed fixed-chunk store, restore byte-identical files and report deterministic storage savings.",\n  "owned_files": [\n    "normalize.py",\n    "engine.py",\n    "report.py",\n    "cli.py"\n  ],\n  "public_api": {\n    "normalize.py": "normalization helpers",\n    "engine.py": "core algorithm",\n    "report.py": "deterministic report",\n    "cli.py": "read input JSON, write output JSON"\n  },\n  "constraints": [\n    "standard library only",\n    "stable ordering",\n    "do not edit contract.json or check_module.py",\n    "python3 check_module.py must pass"\n  ]\n}\n', 'check_module.py': 'import hashlib,json,time\nfrom pathlib import Path\nstarted=time.perf_counter()\nfrom engine import build_store, restore\nfrom report import dedup_report\nfiles={"a":b"abcd"*100,"b":b"abcd"*50+b"wxyz"*50}\nstore=build_store(files,16); assert all(restore(store,k)==v for k,v in files.items())\nbase=bytes((i*37)%256 for i in range(32*1024*1024))\nlarge={f"f{i}": base[i*4096:]+base[:i*4096]+(bytes([i])*512*1024) for i in range(16)}\nfor size in (4096,8192,16384,32768,65536,131072,262144,524288,1048576):\n    out=dedup_report(large,size); assert out["stored_bytes"] <= out["raw_bytes"] and len(out["checksum"]) == 64\nelapsed=time.perf_counter()-started\nowned=[\'normalize.py\',\'engine.py\',\'report.py\',\'cli.py\']\nhashes={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in owned}\nPath(\'.focused-pass.json\').write_text(json.dumps({\'package\':\'content_dedup\',\'passed\':True,\'implementation_hashes\':hashes,\'elapsed_seconds\':elapsed},sort_keys=True,indent=2)+\'\\n\')\nprint(\'FOCUSED_CHECK_PASS\',\'content_dedup\',round(elapsed,3))\n', 'normalize.py': "raise NotImplementedError('implement normalize.py')\n", 'engine.py': "raise NotImplementedError('implement engine.py')\n", 'report.py': "raise NotImplementedError('implement report.py')\n", 'cli.py': 'import argparse, json\nfrom pathlib import Path\nfrom report import dedup_report\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("input"); p.add_argument("output"); a=p.parse_args()\n    data=json.loads(Path(a.input).read_text()); out=dedup_report({k: bytes.fromhex(v) for k,v in data[\'files_hex\'].items()}, int(data[\'chunk_size\']))\n    Path(a.output).parent.mkdir(parents=True,exist_ok=True); Path(a.output).write_text(json.dumps(out,sort_keys=True,indent=2)+"\\n")\nif __name__ == "__main__": main()\n'}, 'version_constraints': {'contract.json': '{\n  "package": "version_constraints",\n  "objective": "Parse semantic versions and compound ranges, choose the highest compatible version and report unresolved packages.",\n  "owned_files": [\n    "normalize.py",\n    "engine.py",\n    "report.py",\n    "cli.py"\n  ],\n  "public_api": {\n    "normalize.py": "normalization helpers",\n    "engine.py": "core algorithm",\n    "report.py": "deterministic report",\n    "cli.py": "read input JSON, write output JSON"\n  },\n  "constraints": [\n    "standard library only",\n    "stable ordering",\n    "do not edit contract.json or check_module.py",\n    "python3 check_module.py must pass"\n  ]\n}\n', 'check_module.py': 'import hashlib,json,time\nfrom pathlib import Path\nstarted=time.perf_counter()\nfrom normalize import satisfies\nfrom engine import select_highest\nfrom report import resolution_report\nassert satisfies("1.4.9", ">=1.2.0 <2.0.0") and not satisfies("2.0.0", "^1.4.0")\nassert select_highest(["1.0.0","1.9.0","2.0.0"],["^1.1.0"]) == "1.9.0"\ncatalog={f"pkg{i}":[f"{major}.{minor}.{patch}" for major in range(4) for minor in range(12) for patch in range(6)] for i in range(180)}\nfor turn in range(60):\n    req={f"pkg{i}":[f">={turn%3}.{i%10}.0",f"<{(turn%3)+2}.0.0"] for i in range(180)}\n    out=resolution_report(catalog,req); assert len(out["selected"]) == 180 and len(out["checksum"]) == 64\nelapsed=time.perf_counter()-started\nowned=[\'normalize.py\',\'engine.py\',\'report.py\',\'cli.py\']\nhashes={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in owned}\nPath(\'.focused-pass.json\').write_text(json.dumps({\'package\':\'version_constraints\',\'passed\':True,\'implementation_hashes\':hashes,\'elapsed_seconds\':elapsed},sort_keys=True,indent=2)+\'\\n\')\nprint(\'FOCUSED_CHECK_PASS\',\'version_constraints\',round(elapsed,3))\n', 'normalize.py': "raise NotImplementedError('implement normalize.py')\n", 'engine.py': "raise NotImplementedError('implement engine.py')\n", 'report.py': "raise NotImplementedError('implement report.py')\n", 'cli.py': 'import argparse, json\nfrom pathlib import Path\nfrom report import resolution_report\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("input"); p.add_argument("output"); a=p.parse_args()\n    data=json.loads(Path(a.input).read_text()); out=resolution_report(data[\'catalog\'], data[\'requirements\'])\n    Path(a.output).parent.mkdir(parents=True,exist_ok=True); Path(a.output).write_text(json.dumps(out,sort_keys=True,indent=2)+"\\n")\nif __name__ == "__main__": main()\n'}, 'provenance_merkle': {'contract.json': '{\n  "package": "provenance_merkle",\n  "objective": "Build domain-separated Merkle trees with odd-leaf duplication, inclusion proofs and tamper verification.",\n  "owned_files": [\n    "normalize.py",\n    "engine.py",\n    "report.py",\n    "cli.py"\n  ],\n  "public_api": {\n    "normalize.py": "normalization helpers",\n    "engine.py": "core algorithm",\n    "report.py": "deterministic report",\n    "cli.py": "read input JSON, write output JSON"\n  },\n  "constraints": [\n    "standard library only",\n    "stable ordering",\n    "do not edit contract.json or check_module.py",\n    "python3 check_module.py must pass"\n  ]\n}\n', 'check_module.py': 'import hashlib,json,time\nfrom pathlib import Path\nstarted=time.perf_counter()\nfrom engine import levels, proof, verify\nfrom report import merkle_report\nsmall=[{"id":i,"value":i*i} for i in range(7)]; root=levels(small)[-1][0].hex()\nassert verify(small[3],proof(small,3),root) and not verify({"id":3,"value":0},proof(small,3),root)\nrecords=[{"id":i,"source":f"repo-{i%97}","digest":f"{i*2654435761:064x}"[-64:]} for i in range(20000)]\nfor turn in range(6):\n    indices=[(turn*997+j*7919)%len(records) for j in range(48)]\n    out=merkle_report(records,indices); assert out["leaf_count"] == len(records) and len(out["root"]) == 64\nelapsed=time.perf_counter()-started\nowned=[\'normalize.py\',\'engine.py\',\'report.py\',\'cli.py\']\nhashes={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in owned}\nPath(\'.focused-pass.json\').write_text(json.dumps({\'package\':\'provenance_merkle\',\'passed\':True,\'implementation_hashes\':hashes,\'elapsed_seconds\':elapsed},sort_keys=True,indent=2)+\'\\n\')\nprint(\'FOCUSED_CHECK_PASS\',\'provenance_merkle\',round(elapsed,3))\n', 'normalize.py': "raise NotImplementedError('implement normalize.py')\n", 'engine.py': "raise NotImplementedError('implement engine.py')\n", 'report.py': "raise NotImplementedError('implement report.py')\n", 'cli.py': 'import argparse, json\nfrom pathlib import Path\nfrom report import merkle_report\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("input"); p.add_argument("output"); a=p.parse_args()\n    data=json.loads(Path(a.input).read_text()); out=merkle_report(data[\'records\'], data[\'sample_indices\'])\n    Path(a.output).parent.mkdir(parents=True,exist_ok=True); Path(a.output).write_text(json.dumps(out,sort_keys=True,indent=2)+"\\n")\nif __name__ == "__main__": main()\n'}}
for package, files in FILES.items():
    target=ROOT/'products'/package; target.mkdir(parents=True,exist_ok=True)
    for name,content in files.items(): (target/name).write_text(content,encoding='utf-8')
manifest={'schema':'dynamic-products/v1','products':sorted(FILES),'contracts':{}}
for package in sorted(FILES):
    raw=(ROOT/'products'/package/'contract.json').read_bytes(); manifest['contracts'][package]=hashlib.sha256(raw).hexdigest()
out=ROOT/'outputs'/'shared_manifest.json'; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(json.dumps(manifest,sort_keys=True,indent=2)+'\n')
print('MATERIALIZED',len(FILES),out)
